<?php
declare(strict_types=1);namespace FMonitor2\YiiRuntime\Controllers;
use FMonitor2\DeadlineTransferCertificate\{DeadlineTransferCertificates as Certificates,MariaDbDeadlineCertificatePageQuery};use FMonitor2\YiiRuntime\PreopeningResources;use Yii;use yii\filters\VerbFilter;use yii\web\Response;
final class DeadlineCertificateController extends PreopeningController
{
 public function behaviors():array{return array_merge(parent::behaviors(),['verbs'=>['class'=>VerbFilter::class,'actions'=>['index'=>['GET','HEAD'],'submit'=>['POST'],'pdf'=>['GET','HEAD'],'index-method'=>['GET','HEAD'],'pdf-method'=>['GET','HEAD']]]]);}
 public function actionIndex(string$id):string|Response{$r=$this->resources();try{$service=$this->service($r);$this->authorizeRead($service);$object=$this->object($id,$r);if(!$object)return$this->status(404);$history=$service->read($this->actor(),$object['caseId']);$names=$this->names($r->db,$r->prefix,array_column($history['history'],'actorId'));return$this->render('@app/app/YiiRuntime/Views/deadline-certificates',['identity'=>Yii::$app->user->identity,'objectId'=>$object['objectId'],'currentDeadline'=>$object['deadline'],'history'=>$history,'actorNames'=>$names,'canWrite'=>$this->cap('deadline_certificate.write'),'csrf'=>Yii::$app->request->csrfToken]);}catch(\DomainException$e){return$this->mapped($e);}catch(\Throwable){return$this->status(503,true);}finally{$r->close();}}
 public function actionSubmit(string$id):Response{$r=$this->resources();$h=null;try{$service=$this->service($r);$this->authorizeWrite($service);$object=$this->object($id,$r);if(!$object)return$this->status(404);$uploaded=\yii\web\UploadedFile::getInstanceByName('pdf');if(!$uploaded||$uploaded->error!==UPLOAD_ERR_OK)return$this->status(422);$h=fopen($uploaded->tempName,'rb');if(!is_resource($h))return$this->status(503,true);$next=static function()use($h):?string{$x=fread($h,65536);if($x===false)throw new \RuntimeException();return$x===''?null:$x;};$b=Yii::$app->request->bodyParams;$request=(string)($b['requestId']??'');$service->submit(['requestId'=>$request,'installationCaseId'=>$object['caseId'],'actorId'=>$this->actor(),'expectedVersion'=>isset($b['expectedVersion'])&&preg_match('/^\d+$/D',(string)$b['expectedVersion'])?(int)$b['expectedVersion']:$b['expectedVersion']??null,'certificateDate'=>$b['certificateDate']??null,'newDeadline'=>$b['newDeadline']??null,'correctionReason'=>($b['correctionReason']??'')===''?null:$b['correctionReason'],'sourceLabel'=>'Справка о переносе срока','sourceLocator'=>'yii-upload/'.$request,'mediaType'=>'application/pdf'],$next);return$this->redirect303('/pilot/objects/'.$object['objectId'].'/deadline-certificates');}catch(\DomainException$e){return$this->mapped($e);}catch(\Throwable){return$this->status(503,true);}finally{if(is_resource($h))fclose($h);$r->close();}}
 public function actionPdf(string$id,string$revision):Response{$r=$this->resources();try{$service=$this->service($r);$this->authorizeRead($service);$object=$this->object($id,$r);if(!$object)return$this->status(404);$history=$service->read($this->actor(),$object['caseId']);if(!in_array((int)$revision,array_column($history['history'],'id'),true))return$this->status(404);$d=$service->download($this->actor(),(int)$revision);$x=Yii::$app->response;$x->format=Response::FORMAT_RAW;$x->statusCode=200;$x->headers->set('Content-Type','application/pdf');$x->headers->set('Content-Disposition','attachment; filename="'.$d['filename'].'"');$x->headers->set('Cache-Control','private, no-store');$x->headers->set('X-Content-Type-Options','nosniff');$x->content=$d['bytes'];return$x;}catch(\DomainException$e){return$this->mapped($e);}catch(\Throwable){return$this->status(503,true);}finally{$r->close();}}
 public function actionIndexMethod(string$id):Response{return$this->canonicalId($id)===null?$this->status(404):$this->methodNotAllowed('GET, HEAD, POST');}public function actionPdfMethod(string$id,string$revision):Response{return$this->canonicalId($id)===null||$this->canonicalId($revision)===null?$this->status(404):$this->methodNotAllowed('GET, HEAD');}
 private function resources():PreopeningResources{return new PreopeningResources(Yii::$app->db);}
 private function service(PreopeningResources$r):Certificates{return Yii::createObject(Certificates::class,[$r->db,$r->prefix,static fn():string=>gmdate('Y-m-d\TH:i:s\Z')]);}
 private function authorizeRead(Certificates$s):void{try{$s->read($this->actor(),PHP_INT_MAX);}catch(\DomainException$e){if($e->getMessage()!=='CASE_NOT_FOUND')throw$e;}}
 private function authorizeWrite(Certificates$s):void{try{$s->submit(['requestId'=>'00000000-0000-4000-8000-000000000000','installationCaseId'=>PHP_INT_MAX,'actorId'=>$this->actor(),'expectedVersion'=>0,'certificateDate'=>'2000-01-01','newDeadline'=>'2000-01-01','correctionReason'=>null,'sourceLabel'=>'authorization','sourceLocator'=>'authorization','mediaType'=>'application/pdf'],static fn():?string=>null);}catch(\DomainException$e){if($e->getMessage()!=='CASE_NOT_FOUND')throw$e;}}
 private function object(string$id,PreopeningResources$r):?array{$id=$this->canonicalId($id);if(!$id)return null;return(new MariaDbDeadlineCertificatePageQuery(Yii::$app->db,$r->db,$r->prefix,(string)getenv('FMONITOR_LEGACY_TABLE_PREFIX')))->object($id);}
 private function mapped(\DomainException$e):Response{return match($e->getMessage()){'FORBIDDEN'=>$this->status(403),'CASE_NOT_FOUND'=>$this->status(404),'OPERATION_CONFLICT','STALE_REVISION'=>$this->status(409),'INVALID_COMMAND','INVALID_PDF'=>$this->status(422),'STORAGE_UNAVAILABLE','OUTCOME_UNKNOWN','CERTIFICATE_EVIDENCE_INVALID'=>$this->status(503,true),default=>$this->status(503,true)};}
 private function names(\mysqli$db,string$p,array$ids):array{return(new MariaDbDeadlineCertificatePageQuery(Yii::$app->db,$db,$p,(string)getenv('FMONITOR_LEGACY_TABLE_PREFIX')))->actorNames($ids);}
}
